def item(head: str, text: str) -> dict[str, str]:
    return {"head": head, "text": text}


def slide(
    section: str,
    title: str,
    lead: str,
    items: list[dict[str, str]],
    notes: str,
    *,
    layout: str = "cards",
    image: str | None = None,
    alt: str = "",
    caption: str = "",
    metric: str = "",
    metric_label: str = "",
    year: str = "",
    refs: list[dict[str, str]] | None = None,
) -> dict:
    reference_list = refs or []
    if reference_list:
        notes += "\n\nИсточники:\n" + "\n".join(f"{ref['label']}: {ref['url']}" for ref in reference_list)
    return {
        "section": section,
        "title": title,
        "lead": lead,
        "items": items,
        "notes": notes,
        "layout": layout,
        "image": image,
        "alt": alt,
        "caption": caption,
        "metric": metric,
        "metric_label": metric_label,
        "year": year,
        "refs": reference_list,
    }


